    while (start < n1 && start < n2 && s1[start] == s2[start]) start++;
    while (n1 > start && n2 > start && s1[n1 - 1] == s2[n2 - 1]) {
        n1--;
        n2--;
    }
    s1 += start;
    s2 += start;
    n1 -= start;
    n2 -= start;
    if (n1 == 0 || n2 == 0) return start;

    if (n1 < n2) {
        const uint8_t *tmp_s = s1; s1 = s2; s2 = tmp_s;
        int tmp_n = n1; n1 = n2; n2 = tmp_n;
    }

    int words = (n2 + 63) >> 6;
    uint64_t masks[256][64];
    memset(masks, 0, sizeof(masks));
    for (int j = 0; j < n2; j++) {
        masks[s2[j]][j >> 6] |= (1ULL << (j & 63));
    }

    uint64_t P[64];
    memset(P, 0, words * sizeof(uint64_t));

    for (int i = 0; i < n1; i++) {
        const uint64_t *M = masks[s1[i]];
        uint64_t carry = 1;
        uint64_t borrow = 0;
        for (int w = 0; w < words; w++) {
            uint64_t p = P[w];
            uint64_t x = p | M[w];
            uint64_t shifted = (p << 1) | carry;
            carry = p >> 63;

            uint64_t sub1 = x - shifted;
            uint64_t b1 = (x < shifted);
            uint64_t y = sub1 - borrow;
            uint64_t b2 = (sub1 < borrow);
            borrow = b1 | b2;

            P[w] = x & (x ^ y);
        }
    }

    int ans = start;
    for (int w = 0; w < words; w++) {
        ans += __builtin_popcountll(P[w]);
    }
    return ans;
}
